import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import * as C from "./strconv.ts";

// Vectors generated by ts/tools/gen-strings-vectors from Go 1.21.13. Errors are
// stored as Go's message text (null for nil). Special floats are stored as the
// strings "NaN", "+Inf" and "-Inf".

interface Vector {
  args: unknown[];
  // For (value, error) functions: { value, err }. Otherwise the plain result.
  want?: unknown;
}

interface VectorFile {
  goVersion: string;
  seed: number;
  generator: string;
  functions: Record<string, Vector[]>;
}

const data: VectorFile = JSON.parse(
  readFileSync(new URL("./testdata/strconv_vectors.json", import.meta.url), "utf8"),
);

function str(x: unknown): string {
  if (typeof x !== "string") {
    throw new TypeError(`expected string, got ${typeof x}`);
  }
  return x;
}

function num(x: unknown): number {
  if (typeof x !== "number") {
    throw new TypeError(`expected number, got ${typeof x}`);
  }
  return x;
}

// floatArg decodes a float argument or value, including the special strings.
function float(x: unknown): number {
  if (x === "NaN") {
    return NaN;
  }
  if (x === "+Inf") {
    return Infinity;
  }
  if (x === "-Inf") {
    return -Infinity;
  }
  return num(x);
}

type Tuple = [number, Error | null];

const calls: Record<string, (a: unknown[]) => unknown> = {
  Itoa: (a) => C.Itoa(num(a[0])),
  FormatInt: (a) => C.FormatInt(num(a[0]), num(a[1])),
  FormatBool: (a) => C.FormatBool(a[0] === true),
  Quote: (a) => C.Quote(str(a[0])),
  Atoi: (a) => C.Atoi(str(a[0])),
  ParseInt: (a) => C.ParseInt(str(a[0]), num(a[1]), num(a[2])),
  ParseFloat: (a) => C.ParseFloat(str(a[0]), num(a[1])),
  FormatFloat: (a) => C.FormatFloat(float(a[0]), str(a[1]), num(a[2]), num(a[3])),
};

test("every function in the vector file has a port", () => {
  for (const fn of Object.keys(data.functions)) {
    assert.ok(fn in calls, `no TypeScript port for ${fn}`);
  }
  assert.equal(Object.keys(data.functions).length, Object.keys(calls).length);
});

// Functions that return (value, error) in Go.
const TUPLE_FUNCTIONS = new Set(["Atoi", "ParseInt", "ParseFloat"]);
const FLOAT_VALUE_FUNCTIONS = new Set(["ParseFloat"]);

for (const [fn, cases] of Object.entries(data.functions)) {
  test(`strconv.${fn} matches ${cases.length} Go vectors`, () => {
    if (fn !== "FormatBool") {
      assert.ok(cases.length >= 40, `${fn} has only ${cases.length} vectors`);
    }
    const run = calls[fn];
    cases.forEach((c, k) => {
      const where = `${fn} case ${k} args=${JSON.stringify(c.args)}`;
      const got = run(c.args);
      if (TUPLE_FUNCTIONS.has(fn)) {
        const [value, err] = got as Tuple;
        const w = c.want as { value: unknown; err: string | null };
        assert.equal(err === null ? null : err.message, w.err, `${where}: error`);
        if (FLOAT_VALUE_FUNCTIONS.has(fn)) {
          // Object.is distinguishes -0 from 0 and treats NaN as equal to NaN.
          const wantValue = float(w.value);
          assert.ok(Object.is(value, wantValue), `${where}: value ${value} want ${wantValue}`);
        } else {
          assert.equal(value, w.value, `${where}: value`);
        }
      } else {
        assert.deepStrictEqual(got, c.want, where);
      }
    });
  });
}

// ---- hand-written checks ----------------------------------------------------

test("Atoi follows Go's grammar: no whitespace, one optional sign, ASCII digits only", () => {
  assert.deepStrictEqual(C.Atoi("+12"), [12, null]);
  assert.deepStrictEqual(C.Atoi("-0"), [0, null]);
  assert.equal(C.Atoi(" 1")[1]?.message, 'strconv.Atoi: parsing " 1": invalid syntax');
  assert.equal(C.Atoi("1 ")[1]?.message, 'strconv.Atoi: parsing "1 ": invalid syntax');
  assert.equal(C.Atoi("١")[1]?.message, 'strconv.Atoi: parsing "١": invalid syntax');
  assert.equal(C.Atoi("1_000")[1]?.message, 'strconv.Atoi: parsing "1_000": invalid syntax');
  assert.equal(C.Atoi("0x10")[1]?.message, 'strconv.Atoi: parsing "0x10": invalid syntax');
  assert.equal(C.Atoi("")[1]?.message, 'strconv.Atoi: parsing "": invalid syntax');
  assert.equal(C.Atoi("abc")[1]?.message, 'strconv.Atoi: parsing "abc": invalid syntax');
  assert.deepStrictEqual(C.Atoi("abc")[0], 0);
});

test("Atoi out of range clamps to the 64-bit limit and reports a range error (value is 2^63 as a double)", () => {
  const [v, err] = C.Atoi("99999999999999999999");
  assert.equal(v, 2 ** 63);
  assert.equal(err?.message, 'strconv.Atoi: parsing "99999999999999999999": value out of range');
  assert.equal(C.Atoi("-99999999999999999999")[0], -(2 ** 63));
});

test("Atoi quotes non-ASCII input in the error message, as Go's Quote does", () => {
  assert.equal(C.Atoi("é\n")[1]?.message, 'strconv.Atoi: parsing "é\\n": invalid syntax');
  assert.equal(C.Atoi("\ud800")[1]?.message, 'strconv.Atoi: parsing "\\ufffd": invalid syntax');
});

test("ParseInt with base 10 and bit size 32 (Lute's call sites): range, clamping and syntax", () => {
  assert.deepStrictEqual(C.ParseInt("2147483647", 10, 32), [2147483647, null]);
  const [hi, hiErr] = C.ParseInt("99999999999", 10, 32);
  assert.equal(hi, 2147483647);
  assert.equal(hiErr?.message, 'strconv.ParseInt: parsing "99999999999": value out of range');
  const [lo, loErr] = C.ParseInt("-99999999999", 10, 32);
  assert.equal(lo, -2147483648);
  assert.equal(loErr?.message, 'strconv.ParseInt: parsing "-99999999999": value out of range');
  assert.equal(C.ParseInt("", 10, 32)[1]?.message, 'strconv.ParseInt: parsing "": invalid syntax');
  assert.equal(C.ParseInt("-", 10, 32)[1]?.message, 'strconv.ParseInt: parsing "-": invalid syntax');
  assert.equal(C.ParseInt("1_0", 10, 32)[1]?.message, 'strconv.ParseInt: parsing "1_0": invalid syntax');
  assert.equal(C.ParseInt("-0x1", 16, 32)[1]?.message, 'strconv.ParseInt: parsing "-0x1": invalid syntax');
});

test("ParseInt with base 16 accepts both letter cases and a sign", () => {
  assert.deepStrictEqual(C.ParseInt("ff", 16, 32), [255, null]);
  assert.deepStrictEqual(C.ParseInt("FF", 16, 32), [255, null]);
  assert.deepStrictEqual(C.ParseInt("+1f", 16, 32), [31, null]);
  assert.equal(C.ParseInt("99999999999", 16, 32)[0], 2147483647);
});

test("ParseInt reports invalid base and bit size as Go does", () => {
  assert.equal(C.ParseInt("10", 1, 64)[1]?.message, 'strconv.ParseInt: parsing "10": invalid base 1');
  assert.equal(C.ParseInt("10", 10, 65)[1]?.message, 'strconv.ParseInt: parsing "10": invalid bit size 65');
});

test("Itoa and FormatInt are exact for integers up to 2^53", () => {
  assert.equal(C.Itoa(-0), "0");
  assert.equal(C.Itoa(2 ** 53 - 1), "9007199254740991");
  assert.equal(C.FormatInt(-255, 16), "-ff");
  assert.equal(C.FormatInt(35, 36), "z");
  assert.throws(() => C.FormatInt(1, 1), /illegal AppendInt\/FormatInt base/);
  assert.throws(() => C.Itoa(1.5), /not an integer/);
});

test("FormatBool", () => {
  assert.equal(C.FormatBool(true), "true");
  assert.equal(C.FormatBool(false), "false");
});

test("ParseFloat grammar: decimal, inf/infinity, nan, overflow to Inf with a range error", () => {
  assert.deepStrictEqual(C.ParseFloat("5.", 64), [5, null]);
  assert.deepStrictEqual(C.ParseFloat(".5", 64), [0.5, null]);
  assert.equal(C.ParseFloat("+.e1", 64)[1]?.message, 'strconv.ParseFloat: parsing "+.e1": invalid syntax');
  assert.equal(C.ParseFloat("1e", 64)[1]?.message, 'strconv.ParseFloat: parsing "1e": invalid syntax');
  assert.equal(C.ParseFloat(" 5", 64)[1]?.message, 'strconv.ParseFloat: parsing " 5": invalid syntax');
  assert.equal(C.ParseFloat("+nan", 64)[1]?.message, 'strconv.ParseFloat: parsing "+nan": invalid syntax');
  assert.equal(C.ParseFloat("-Infinity", 64)[0], -Infinity);
  assert.ok(Number.isNaN(C.ParseFloat("NaN", 64)[0]));
  const [big, bigErr] = C.ParseFloat("1e400", 64);
  assert.equal(big, Infinity);
  assert.equal(bigErr?.message, 'strconv.ParseFloat: parsing "1e400": value out of range');
  assert.deepStrictEqual(C.ParseFloat("1e-400", 64), [0, null]);
});

test("ParseFloat rejects forms that are not implemented (throws instead of approximating)", () => {
  assert.throws(() => C.ParseFloat("0x1p4", 64), /unsupported arguments/);
  assert.throws(() => C.ParseFloat("1_0", 64), /unsupported arguments/);
  assert.throws(() => C.ParseFloat("1", 32), /unsupported arguments/);
});

test("FormatFloat 'f' rounds the exact binary value, ties to even", () => {
  assert.equal(C.FormatFloat(0.0078125, "f", 6, 64), "0.007812");
  assert.equal(C.FormatFloat(0.5, "f", 0, 64), "0");
  assert.equal(C.FormatFloat(1.5, "f", 0, 64), "2");
  assert.equal(C.FormatFloat(2.5, "f", 0, 64), "2");
  assert.equal(C.FormatFloat(1.0000005, "f", 6, 64), "1.000001");
  assert.equal(C.FormatFloat(-0.0000001, "f", 6, 64), "-0.000000");
  assert.equal(C.FormatFloat(-0, "f", 6, 64), "-0.000000");
  assert.equal(C.FormatFloat(1.2, "f", 6, 64), "1.200000");
  assert.equal(C.FormatFloat(1e22, "f", 6, 64), "10000000000000000000000.000000");
  assert.equal(C.FormatFloat(Infinity, "f", 6, 64), "+Inf");
  assert.equal(C.FormatFloat(-Infinity, "f", 6, 64), "-Inf");
  assert.equal(C.FormatFloat(NaN, "f", 6, 64), "NaN");
});

test("FormatFloat rejects formats and precisions it does not implement", () => {
  assert.throws(() => C.FormatFloat(1.5, "e", 6, 64), /unsupported arguments/);
  assert.throws(() => C.FormatFloat(1.5, "f", -1, 64), /unsupported arguments/);
  assert.throws(() => C.FormatFloat(1.5, "f", 6, 32), /unsupported arguments/);
});

test("Quote escapes as Go does: short escapes, \\xNN, \\uNNNN, \\UNNNNNNNN, printable runes raw", () => {
  assert.equal(C.Quote("\"\\"), '"\\"\\\\"');
  assert.equal(C.Quote("\u0007\b\f\n\r\t\u000b"), '"\\a\\b\\f\\n\\r\\t\\v"');
  assert.equal(C.Quote("\u0000\u001f\u007f"), '"\\x00\\x1f\\x7f"');
  assert.equal(C.Quote("'"), '"\'"');
  assert.equal(C.Quote("\u0085 ​ ﻿"), '"\\u0085\\u00a0\\u200b\\u2028\\ufeff"');
  assert.equal(C.Quote("­͸"), '"\\u00ad\\ue000\\u0378"');
  assert.equal(C.Quote("\u{e0001}\u{10ffff}"), '"\\U000e0001\\U0010ffff"');
  assert.equal(C.Quote("日本語😀é"), '"日本語😀é"');
  assert.equal(C.Quote("�"), '"�"');
  assert.equal(C.Quote(""), '""');
});

test("Quote of an unpaired surrogate writes \\ufffd (Go's invalid-rune path), without throwing", () => {
  assert.equal(C.Quote("\ud800"), '"\\ufffd"');
  assert.equal(C.Quote("a\udc00b"), '"a\\ufffdb"');
  assert.equal(C.Quote("😀\ud800"), '"😀\\ufffd"');
});

test("ParseInt with base 0 throws (prefix detection is not implemented)", () => {
  assert.throws(() => C.ParseInt("10", 0, 64), /unsupported arguments/);
});
